/**
 * Baduma.sl — Verify WhatsApp OTP (custom mode)
 *
 * Verifies an OTP that was generated and sent by the `send-whatsapp-otp`
 * Edge Function in "custom" mode. This is used when the OTP was sent via a
 * custom WhatsApp template (not generated by Supabase Auth), so
 * `supabase.auth.verifyOtp()` cannot be used.
 *
 * On success, the Edge Function ensures a Supabase Auth user exists for the
 * phone number and returns the user info.
 *
 * NOTE: This SDK version (auth-js v2.118) does not expose
 * `admin.getUserByPhone()` or `admin.generateUserToken()`. User lookup is done
 * via `listUsers()` pagination, and the session is obtained by the client via
 * the native flow (`signInWithOtp` + `verifyOtp`) — see docs/whatsapp-otp-setup.md.
 *
 * Required env vars (set in the Supabase Dashboard → Edge Functions → Variables):
 *   SUPABASE_URL                 — e.g. https://xyzcompany.supabase.co
 *   SUPABASE_SERVICE_ROLE_KEY    — service role key (secret)
 */

import { createClient } from '@supabase/supabase-js';

const SUPABASE_URL = process.env.SUPABASE_URL;
const SUPABASE_SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

function normalizePhone(phone: unknown): string {
  return String(phone || '').replace(/[\s-]/g, '');
}

export default async function handler(req: Request): Promise<Response> {
  if (req.method !== 'POST') {
    return new Response('Method not allowed', { status: 405 });
  }

  const body = await req.json().catch(() => ({}));
  const phone = normalizePhone(body.phone);
  const token = String(body.token || '');

  if (!/^\+?[0-9]{7,15}$/.test(phone) || !/^[0-9]{6}$/.test(token)) {
    return new Response(JSON.stringify({ error: 'Invalid phone or token' }), { status: 400 });
  }

  const supabase = createClient(SUPABASE_URL!, SUPABASE_SERVICE_ROLE_KEY!);

  // 1. Check the OTP against the otp_codes table.
  const { data: otpRow, error: otpError } = await supabase
    .from('otp_codes')
    .select('id')
    .eq('phone', phone)
    .eq('code', token)
    .eq('used', false)
    .gt('expires_at', new Date().toISOString())
    .maybeSingle();

  if (otpError || !otpRow) {
    return new Response(JSON.stringify({ error: 'Invalid or expired code' }), { status: 400 });
  }

  // 2. Mark the OTP as used (single-use).
  await supabase.from('otp_codes').update({ used: true }).eq('id', otpRow.id);

  // 3. Find an existing user for this phone, or create one.
  let user = null;
  const { data: users, error: listError } = await supabase.auth.admin.listUsers({
    page: 1,
    perPage: 1000,
  });
  if (!listError && users?.users) {
    user = users.users.find((u) => u.phone === phone) || null;
  }

  if (!user) {
    const { data: created, error: createError } = await supabase.auth.admin.createUser({
      phone,
      email_confirm: true,
      phone_confirm: true,
    });
    if (createError) {
      return new Response(JSON.stringify({ error: createError.message }), { status: 400 });
    }
    user = created?.user || null;
  }

  // 4. Return the user info. The client obtains a session via the native flow
  //    (signInWithOtp + verifyOtp) — see the setup guide.
  return new Response(
    JSON.stringify({
      success: true,
      user: { id: user.id, phone: user.phone },
    }),
    { status: 200 }
  );
}
